// 1. Basic C-string insertion (at pos, length n)

void insert(size_type pos, const char* s, size_type n) {
    if (n == 0) return;
    const size_type current_size = size();
    const size_type required = current_size + n;

    if (required > capacity()) {
        // Relocation needed: Reallocate and copy existing data
        // Optimization: Use growth factor (1.5x or 2x)
        size_type new_cap = calculate_new_capacity(required);
        // Copy original prefix, new data, then original suffix
        reallocate_and_copy(pos, s, n, new_cap);
    } else {
        // In-place shift (if capacity sufficient)
        // memmove: shifts existing suffix right by 'n'
        std::memmove(data_ + pos + n, data_ + pos, current_size - pos);
        // memcpy: copy new data 's' into the gap
        std::memcpy(data_ + pos, s, n);
    }
}

// 2. Optimization: Insert specific character 'c' repeatedly 'count' times

void insert(size_type pos, size_type count, char c) {
    // Similar growth check
    // If relocation: use custom fill function during copy
    // If in-place:
    std::memmove(data_ + pos + count, data_ + pos, size() - pos);
    // Optimization: Use compiler-optimized memset/std::fill
    std::fill(data_ + pos, data_ + pos + count, c);
}
